{"url":"https://upload.meeshosupplyassets.com/cataloging/1791393253234/ElegantButterflyGoldBangleCelebrationAd.png","alt":"Korean Butterfly Charm Gold Bangle"}],"active":true,"sellIndividually":true,"salePricePaise":19900,"prepackagedRetail":true,"retail":{"genericName":"Bracelet & Bangles","netQuantity":"1 N","manufacturerOrPackerName":"Celebration","manufacturerOrPackerAddress":"Sikar, Rajasthan, India - 332001","importerName":"Celebration","importerAddress":"Sikar, Rajasthan, India - 332001","countryOfOrigin":"South Korea","consumerCare":"Celebration, Sikar, Rajasthan 332001","mrpPaise":39900,"unitSalePrice":"₹199 per piece, delivery included"},"icon":"✦"}]$products$::jsonb)
),
transformed AS (
  SELECT cc.id,
         jsonb_set(
           cc.payload,
           '{products}',
           COALESCE(cc.payload->'products','[]'::jsonb) ||
           COALESCE((
             SELECT jsonb_agg(a.product)
             FROM additions a
             WHERE NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(COALESCE(cc.payload->'products','[]'::jsonb)) existing(product)
               WHERE existing.product->>'id' = a.product->>'id'
             )
           ), '[]'::jsonb),
           true
         ) AS payload
  FROM catalog_config cc
  WHERE cc.id='primary'
),
updated AS (
  UPDATE catalog_config cc
     SET payload = transformed.payload,
         version = cc.version + 1,
         updated_at = now()
    FROM transformed
   WHERE cc.id = transformed.id
  RETURNING cc.version, cc.payload
)
INSERT INTO catalog_revisions (version, payload)
SELECT version, payload FROM updated;

DELETE FROM catalog_drafts WHERE id='primary';
